  heroClientTitle2: "de la sécurité",
  heroClientTitle3: "",
  heroClientDesc: "Tous les spécialistes de la sécurité au même endroit. Plus besoin de chercher sur différents sites : choisissez un service, comparez les prestataires vérifiés par note et par affaires, et contactez-les directement. Gratuit pour les clients.",
