  lpFaqTag: "Questions / Réponses",
  lpFaqTitle: "Questions fréquentes",
  lpFaq1Q: "Combien coûte la plateforme ?",
  lpFaq1A: "La plateforme est entièrement gratuite pour les clients — vous cherchez des spécialistes et les contactez sans frais. Les prestataires ne paient qu'un abonnement, sans commission sur les commandes.",
  lpFaq2Q: "Comment vérifiez-vous les spécialistes ?",
  lpFaq2A: "Chaque prestataire fait l'objet d'une vérification des documents et des qualifications. Le badge « Licence » n'apparaît qu'après confirmation de la licence, du statut d'entrepreneur/société et de la vérification complète par un modérateur.",
  lpFaq3Q: "Est-il sûr de partager mes données ?",
  lpFaq3A: "Oui. Nous utilisons le chiffrement, une messagerie sécurisée et nous conformons au RGPD et à la loi russe. Les données de paiement sont traitées par des prestataires certifiés — nous ne stockons pas les numéros de carte.",
  lpFaq4Q: "Comment le service du prestataire est-il payé ?",
  lpFaq4A: "Les modalités de paiement et de service sont convenues directement entre le client et le prestataire. La plateforme est un intermédiaire d'information et n'est pas partie à la transaction.",
  lpFaq5Q: "Puis-je travailler sous un pseudonyme ?",
  lpFaq5A: "Oui. Compte tenu de la nature du secteur de la sécurité, les prestataires peuvent utiliser un pseudonyme et limiter la visibilité de certaines données — mais chacun passe la vérification auprès de la plateforme.",
  lpFaq6Q: "Dans quels pays la plateforme opère-t-elle ?",
  lpFaq6A: "La plateforme est internationale : des spécialistes sont présents dans plus de 15 pays. Le fuseau horaire et la disponibilité pour les appels sont pris en compte automatiquement.",
  pdAvailTitle: "Disponibilité pour les appels",
