  aboutTag: "À propos de l'entreprise",
  aboutPageTitle: "À propos de ЩИТ",
  aboutIntro: "Une plateforme internationale reliant des spécialistes de la sécurité vérifiés à des clients du monde entier — dans un espace unique et sécurisé.",
  aboutMissionTitle: "Notre mission",
  aboutMissionText: "Nous rendons la recherche de spécialistes de la sécurité simple et sûre. Détectives, gardes du corps, polygraphistes, experts en cybersécurité et agences de sécurité étaient auparavant dispersés sur différents sites et contacts personnels. ЩИТ les rassemble en un seul endroit, avec vérification des documents et communication sécurisée, afin que les clients puissent faire confiance à un professionnel et que les spécialistes reçoivent des commandes sans dépenses publicitaires.",
  aboutStoryTitle: "Comment tout a commencé",
  aboutStoryText: "ЩИТ a été créé en réponse à un besoin du marché : les clients peinaient à trouver un spécialiste de la sécurité vérifié, tandis que les spécialistes peinaient à atteindre les clients sans intermédiaires ni publicité coûteuse. Nous avons uni un marché fragmenté en un réseau international unique avec vérification des licences, suivi de la réputation et une communauté professionnelle privée.",
