  lpFaqTag: "Fragen & Antworten",
  lpFaqTitle: "Häufig gestellte Fragen",
  lpFaq1Q: "Was kostet die Plattform?",
  lpFaq1A: "Die Plattform ist für Kunden völlig kostenlos — Sie suchen Spezialisten und kontaktieren sie ohne Kosten. Anbieter zahlen nur für ein Abonnement, ohne Provision auf Aufträge.",
  lpFaq2Q: "Wie verifizieren Sie Spezialisten?",
  lpFaq2A: "Jeder Anbieter durchläuft eine Prüfung von Dokumenten und Qualifikationen. Das Abzeichen „Lizenz“ erscheint erst nach Bestätigung der Lizenz, des Unternehmer-/Gesellschaftsstatus und der vollständigen Moderatorprüfung.",
  lpFaq3Q: "Ist es sicher, meine Daten zu teilen?",
  lpFaq3A: "Ja. Wir verwenden Verschlüsselung, einen sicheren Chat und halten uns an die DSGVO und russisches Recht. Zahlungsdaten werden von zertifizierten Anbietern verarbeitet — wir speichern keine Kartennummern.",
  lpFaq4Q: "Wie wird der Dienst des Anbieters bezahlt?",
  lpFaq4A: "Zahlungs- und Dienstbedingungen werden direkt zwischen dem Kunden und dem Anbieter vereinbart. Die Plattform ist ein Informationsvermittler und nicht Partei der Transaktion.",
  lpFaq5Q: "Kann ich unter einem Pseudonym arbeiten?",
  lpFaq5A: "Ja. Angesichts der Natur des Sicherheitsbereichs können Anbieter ein Pseudonym verwenden und die Sichtbarkeit einiger Daten einschränken — aber jeder durchläuft die Verifizierung bei der Plattform.",
  lpFaq6Q: "In welchen Ländern ist die Plattform tätig?",
  lpFaq6A: "Die Plattform ist international: Spezialisten sind in über 15 Ländern vertreten. Zeitzone und Anruf-Verfügbarkeit werden automatisch berücksichtigt.",
  pdAvailTitle: "Anruf-Verfügbarkeit",
  pdAvailHint: "Legen Sie Ruhezeiten fest — die Anruf-Schaltfläche ist in dieser Zeit deaktiviert. Die Zeitzone wird für Sie und den Kunden automatisch erkannt.",
