  aboutTag: "Über das Unternehmen",
  aboutPageTitle: "Über ЩИТ",
  aboutIntro: "Eine internationale Plattform, die verifizierte Sicherheitsspezialisten mit Kunden weltweit verbindet — in einem sicheren Raum.",
  aboutMissionTitle: "Unsere Mission",
  aboutMissionText: "Wir machen die Suche nach Sicherheitsspezialisten einfach und sicher. Detektive, Personenschützer, Polygraf-Prüfer, Cybersicherheitsexperten und Sicherheitsagenturen waren früher über verschiedene Websites und persönliche Kontakte verstreut. ЩИТ vereint sie an einem Ort, mit Dokumentenprüfung und sicherer Kommunikation, damit Kunden einem Profi vertrauen und Spezialisten ohne Werbeausgaben Aufträge erhalten können.",
  aboutStoryTitle: "Wie alles begann",
  aboutStoryText: "ЩИТ entstand als Antwort auf einen Marktbedarf: Kunden hatten Schwierigkeiten, einen verifizierten Sicherheitsspezialisten zu finden, während Spezialisten Schwierigkeiten hatten, Kunden ohne Vermittler und teure Werbung zu erreichen. Wir haben einen fragmentierten Markt zu einem einzigen internationalen Netzwerk mit Lizenzprüfung, Reputationsverfolgung und einer privaten professionellen Community vereint.",
