  lpFaqTag: "Q & A",
  lpFaqTitle: "よくある質問",
  lpFaq1Q: "プラットフォームの料金はいくらですか？",
  lpFaq1A: "クライアントにとってプラットフォームは完全に無料です — 専門家を検索し、無料で連絡できます。提供者はサブスクリプションのみを支払い、受注に手数料はかかりません。",
  lpFaq2Q: "専門家はどのように認証していますか？",
  lpFaq2A: "各提供者は書類と資格の認証を受けます。「ライセンス」バッジは、ライセンス、個人事業主/法人ステータス、モデレーターによる完全な認証が確認された後にのみ表示されます。",
  lpFaq3Q: "データを共有しても安全ですか？",
  lpFaq3A: "はい。当社は暗号化と安全なチャットを使用し、GDPRおよびロシアの法律に準拠しています。支払いデータは認証済みの事業者によって処理され、カード番号は保存しません。",
  lpFaq4Q: "提供者のサービス料はどのように支払いますか？",
  lpFaq4A: "支払いとサービスの条件は、クライアントと提供者の間で直接取り決められます。プラットフォームは情報仲介者であり、取引の当事者ではありません。",
  lpFaq5Q: "仮名で活動できますか？",
