  lpFaqTitle: "الأسئلة الشائعة",
  lpFaq1Q: "كم تكلّف المنصة؟",
  lpFaq1A: "المنصة مجانية تمامًا للعملاء — تبحث عن الخبراء وتتواصل معهم دون تكلفة. لا يدفع مقدّمو الخدمة سوى الاشتراك، دون عمولة على الطلبات.",
  lpFaq2Q: "كيف توثّقون الخبراء؟",
  lpFaq2A: "يخضع كل مقدّم خدمة لتوثيق المستندات والمؤهلات. لا تظهر شارة «ترخيص» إلا بعد تأكيد الترخيص وحالة رائد الأعمال/الشركة والتوثيق الكامل من المشرف.",
  lpFaq3Q: "هل مشاركة بياناتي آمنة؟",
  lpFaq3A: "نعم. نستخدم التشفير ودردشة آمنة ونلتزم باللائحة العامة لحماية البيانات والقانون الروسي. تُعالَج بيانات الدفع بواسطة مزوّدين معتمدين — ولا نخزّن أرقام البطاقات.",
  lpFaq4Q: "كيف يُدفع مقابل خدمة مقدّم الخدمة؟",
  lpFaq4A: "يُتّفق على شروط الدفع والخدمة مباشرة بين العميل ومقدّم الخدمة. المنصة وسيط معلوماتي وليست طرفًا في الصفقة.",
  lpFaq5Q: "هل يمكنني العمل باسم مستعار؟",
  lpFaq5A: "نعم. نظرًا لطبيعة مجال الأمن، يجوز لمقدّمي الخدمة استخدام اسم مستعار وتقييد ظهور بعض البيانات — لكن الجميع يجتاز التوثيق لدى المنصة.",
  lpFaq6Q: "في أي دول تعمل المنصة؟",
  lpFaq6A: "المنصة دولية: يتواجد الخبراء في أكثر من 15 دولة. تُراعى المنطقة الزمنية وتوفّر الاتصال تلقائيًا.",
