  aboutIntro: "منصة دولية تربط خبراء الأمن الموثّقين بالعملاء حول العالم — في مساحة آمنة واحدة.",
  aboutMissionTitle: "مهمتنا",
  aboutMissionText: "نجعل البحث عن خبراء الأمن بسيطًا وآمنًا. كان المحققون والحراس الشخصيون وفاحصو كشف الكذب وخبراء الأمن السيبراني وشركات الأمن موزّعين سابقًا على مواقع مختلفة وجهات اتصال شخصية. تجمعهم ЩИТ في مكان واحد، مع توثيق المستندات وتواصل آمن، ليتمكّن العملاء من الوثوق بمحترف ويحصل الخبراء على الطلبات دون إنفاق إعلاني.",
  aboutStoryTitle: "كيف بدأ الأمر",
  aboutStoryText: "أُنشئت ЩИТ استجابةً لحاجة السوق: كان العملاء يجدون صعوبة في إيجاد خبير أمن موثّق، بينما كان الخبراء يجدون صعوبة في الوصول إلى العملاء دون وسطاء وإعلانات مكلفة. وحّدنا سوقًا مجزّأً في شبكة دولية واحدة مع توثيق التراخيص وتتبّع السمعة ومجتمع مهني خاص.",
