  heroDesc: "קהילה בינלאומית ומאומתת של בודקי פוליגרף, חוקרים פרטיים, מומחי TSCM, חברות אבטחה ומומחי אבטחה ארגונית. תיקים, שירותים, קורסים וקשרים עסקיים — הכול במקום אחד.",
