  secTag: "אבטחה",
  secTitle: "הצפנה והגנה על נתונים",
  secDesc: "אנו מיישמים הגנה רב-שכבתית. סיסמאות, נתונים אישיים והודעות מוצפנים לפני שמירתם במסד הנתונים — מהכניסה ועד האחסון וההודעות.",
  sec1Title: "הגנה על הכניסה",
  sec1Desc: "סיסמאות נשמרות כגיבובים בלתי הפיכים, הפעלות מוגנות באמצעות אסימונים, אימות דו-שלבי זמין",
  sec2Title: "נתונים אישיים",
  sec2Desc: "מספרי טלפון, כתובות דוא\"ל, שמות מלאים ונתוני דרכון מוצפנים ב-AES לפני כתיבתם למסד הנתונים",
  sec3Title: "הודעות פרטיות מוצפנות",
