  lpFaqTitle: "שאלות נפוצות",
  lpFaq1Q: "כמה עולה הפלטפורמה?",
  lpFaq1A: "הפלטפורמה חינמית לחלוטין ללקוחות — אתם מחפשים מומחים ויוצרים איתם קשר ללא עלות. נותני השירות משלמים רק על מנוי, ללא עמלה על הזמנות.",
  lpFaq2Q: "כיצד אתם מאמתים מומחים?",
  lpFaq2A: "כל נותן שירות עובר אימות מסמכים וכישורים. תג «רישיון» מופיע רק לאחר אישור הרישיון, מעמד עוסק/חברה ואימות מלא של מנהל.",
  lpFaq3Q: "האם בטוח לשתף את הנתונים שלי?",
  lpFaq3A: "כן. אנו משתמשים בהצפנה, בצ'אט מאובטח ועומדים ב-GDPR ובחוק הרוסי. נתוני התשלום מעובדים על ידי ספקים מוסמכים — איננו שומרים מספרי כרטיס.",
  lpFaq4Q: "כיצד משולם עבור שירות נותן השירות?",
  lpFaq4A: "תנאי התשלום והשירות מוסכמים ישירות בין הלקוח לנותן השירות. הפלטפורמה היא מתווכת מידע ואינה צד לעסקה.",
  lpFaq5Q: "האם אני יכול לעבוד תחת כינוי?",
  lpFaq5A: "כן. בהתחשב באופיו של תחום האבטחה, נותני שירות רשאים להשתמש בכינוי ולהגביל את הנראות של חלק מהנתונים — אך כולם עוברים אימות מול הפלטפורמה.",
  lpFaq6Q: "באילו מדינות הפלטפורמה פועלת?",
  lpFaq6A: "הפלטפורמה בינלאומית: מומחים נמצאים ביותר מ-15 מדינות. אזור הזמן וזמינות השיחות נלקחים בחשבון אוטומטית.",
